## Summary

Implement reading bug data from the state branch when Store is in StateBranch mode.

## Implementation

In `src/store.rs`:

```rust
impl Store {
    /// Read bug events from state branch
    fn read_from_state_branch(&self, bug_id: &str) -> Result<Vec<Event>> {
        let path = format!(".docket/bugs/{}/{}.jsonl", &bug_id[..1], bug_id);
        let content = jj::read_state_file(&path)?;
        parse_jsonl(&content)
    }

    /// List all bugs from state branch
    fn list_from_state_branch(&self) -> Result<Vec<Bug>> {
        let files = jj::list_state_files(".docket/bugs/*/*.jsonl")?;
        // Parse each file and derive bugs
    }

    // Update existing methods to dispatch based on mode
    pub fn get_bug(&self, id: &str) -> Result<Bug> {
        match &self.mode {
            StoreMode::FileSystem { .. } => self.get_bug_filesystem(id),
            StoreMode::StateBranch { .. } => self.get_bug_state_branch(id),
        }
    }
}
```

